 rows.sort((a,b)=>Number(b[0])-Number(a[0]));for(const [,row] of rows)box.append(row);
 const feedback=element('p',undefined,'error');feedback.id='active-ai-feedback';feedback.setAttribute('role','status');box.append(feedback);
