 for(const task of tasks){const row=element('button',undefined,'item-row'+(task.id===selectedTaskId?' selected':''));row.type='button';row.append(element('strong',task.title),element('span',`${statusText(task)} · ${safeTime(task.started_at)}`));row.onclick=()=>selectTask(task.id);list.append(row);}
 const task=tasks.find(item=>item.id===selectedTaskId);if(!task)return;rememberTaskDisclosures(taskDisclosureState,detail.dataset.taskId,detail.querySelector('.technical'));for(const open of detail.querySelectorAll('.task-event[open]'))expandedTaskEvents.add(open.dataset.eventId);detail.replaceChildren(mobileBack(detail),element('h2',task.title),element('p',`${statusText(task)} · ${safeTime(task.observed_at||task.started_at)} · 사용한 AI: ${routeText(task.route)}`,'muted'));detail.dataset.taskId=task.id;
