 const technical=element('details',undefined,'technical');technical.append(element('summary','실행 상세'),element('p',`요청 ID ${task.id} · 요청 경로 ${requestSource(task)} · 사용한 AI ${routeText(task.route)}`));let original;if(task.request){original=element('details');original.append(element('summary','원래 요청 보기'),element('p',task.request));technical.append(original);}restoreTaskDisclosures(taskDisclosureState,task.id,technical,original);if(task.source_references?.length)technical.append(element('p','사용한 근거: '+task.source_references.join(' · ')));detail.append(technical);
