function recordKey(item){return `${item.type}:${item.id}`;}
function filteredRecords(){return lastRecords?recordItems(lastRecords):filterLocalRecords(lastSpace,$('record-query').value,$('record-filter').value);}
async function loadRecords({append=false,refreshLoaded=false,throwOnError=false}={}){const query=$('record-query').value.trim(),filter=$('record-filter').value,request=++recordLoadSequence,start=append?(lastRecords?.items?.length||0):0,target=refreshLoaded?Math.max(100,lastRecords?.items?.length||0):start+100;try{let offset=start,records=null,items=[];do{const page=await api('/api/personal-records?'+new URLSearchParams({query,filter,limit:'100',offset:String(offset)}));if(request!==recordLoadSequence||query!==$('record-query').value.trim()||filter!==$('record-filter').value)return false;records=page;items.push(...page.items);offset+=page.items.length;if(!page.has_more||!page.items.length||offset>=target)break;}while(true);records.query=query;records.filter=filter;records.items=append&&lastRecords?[...lastRecords.items,...items]:items;lastRecords=records;recordRenderFingerprint='';renderRecords();$('record-search-feedback').textContent=query?`로컬 원문 기록 ${records.match_count}개를 찾았습니다.`:'';return true;}catch(error){if(request===recordLoadSequence)setError('record-search-feedback',error);if(throwOnError)throw error;return false;}}
function refreshLoadedRecords(){if(recordRefreshPromise)return recordRefreshPromise;recordRefreshPromise=loadRecords({refreshLoaded:true}).finally(()=>{recordRefreshPromise=null;});return recordRefreshPromise;}
function renderRecordCounts(){const counts=lastRecords?.counts||{saved:0,note:0,memory:0,temporary:0,artifact:0};if(!lastRecords)recordItems(lastSpace).forEach(row=>counts[row.type]=(counts[row.type]||0)+1);const box=$('record-counts');box.replaceChildren();if(counts.saved)box.append(element('span',`메모 · 기억 ${counts.saved}개 · 유형 미제공`,'count-chip'));[['메모','note'],['기억','memory'],['임시 자료','temporary'],['저장된 결과','artifact']].forEach(([label,key])=>box.append(element('span',`${label} ${counts[key]||0}개`,'count-chip')));}
function renderRecords(){
 const list=$('record-list'),detail=$('record-detail'),rows=filteredRecords();
 if(!rows.length){clearMobileDetailWhenEmpty(detail,rows);const fingerprint=JSON.stringify(['empty',$('record-query').value,$('record-filter').value,recordDeletePending]);if(recordRenderFingerprint===fingerprint)return;recordRenderFingerprint=fingerprint;renderRecordCounts();list.replaceChildren();list.append(element('p','조건에 맞는 저장 기록이 없습니다. 대화 이력과 저장한 기록은 구분됩니다.','muted'));detail.replaceChildren(element('p','기록을 선택하면 세부 내용을 확인할 수 있습니다.','empty-state'));return;}
 if(!selectedRecordKey||!rows.some(item=>recordKey(item)===selectedRecordKey))selectedRecordKey=recordKey(rows[0]);
 const fingerprint=JSON.stringify([rows,selectedRecordKey,recordDeletePending,$('record-query').value,$('record-filter').value]);if(recordRenderFingerprint===fingerprint)return;recordRenderFingerprint=fingerprint;renderRecordCounts();list.replaceChildren();
 for(const item of rows){const key=recordKey(item),button=element('button',undefined,'item-row'+(key===selectedRecordKey?' selected':''));button.type='button';button.append(element('strong',item.memory_key||item.content||item.label),element('span',`${item.label} · ${safeTime(item.created||item.captured_at)}`));button.onclick=()=>{selectedRecordKey=key;recordRenderFingerprint='';renderRecords();openMobileDetail(detail);};list.append(button);}
 if(lastRecords?.has_more){const more=element('button','더 보기','item-row');more.type='button';more.onclick=()=>busy(more,()=>loadRecords({append:true}));list.append(more);}
 const item=rows.find(row=>recordKey(row)===selectedRecordKey);detail.replaceChildren(mobileBack(detail),element('p',item.label,'eyebrow'),element('h2',item.memory_key||item.label),element('p',item.content||'내용 원문은 이 화면에 보관되지 않습니다.'));
 if(item.type==='artifact')detail.append(element('p',`프로젝트 ${item.workspace_id||'미지정'} · 작업 ${item.job_id||'미지정'}`,'muted'));if(item.type==='temporary')detail.append(element('p',`만료 ${safeTime(item.expires_at)} · ${item.sharing_state||'공유 상태 알 수 없음'}`,'muted'));
 if(item.deleteKind){const actions=element('div',undefined,'record-actions');const remove=element('button',recordDeletePending===selectedRecordKey?'삭제 확인':'삭제');remove.type='button';remove.onclick=async()=>{if(recordDeletePending!==selectedRecordKey){recordDeletePending=selectedRecordKey;recordRenderFingerprint='';renderRecords();return;}recordLoadSequence++;if(shouldInvalidateWorkspaceDetailForDeletion(item,selectedWorkspaceId))workspaceDetailSequence++;try{const deleted=await api('/api/personal-space/'+item.deleteKind+'/'+encodeURIComponent(item.id),undefined,'DELETE');recordDeletePending='';selectedRecordKey='';if(lastRecords){lastRecords.items=lastRecords.items.filter(row=>recordKey(row)!==recordKey(item));lastRecords.match_count=Math.max(0,(lastRecords.match_count||0)-1);if(lastRecords.counts&&lastRecords.counts[item.type]>0)lastRecords.counts[item.type]--;recordRenderFingerprint='';renderRecords();}await loadRecords({refreshLoaded:true,throwOnError:true});if(deleted.workspace_id){workspaceResultSummaries.delete(deleted.workspace_id);lastHome=await api('/api/home');renderWorkspaces(lastHome,lastState);await loadWorkspaceResultSummaries(lastHome.workspaces);if(selectedWorkspaceId===deleted.workspace_id)await selectWorkspace(deleted.workspace_id);}}catch(error){setError('record-search-feedback',error);}};actions.append(remove);detail.append(actions);}
}
$('record-search').onsubmit=event=>{event.preventDefault();void loadRecords();};
$('record-query').oninput=()=>{$('record-search-feedback').textContent='';void loadRecords();};
$('record-filter').onchange=()=>{recordDeletePending='';void loadRecords();};

// Pending MemoryCandidates. `/api/personal-space` already carries the pending
// count and content, but not the `work_ref` or `content_digest` a decision
// needs, so the count keeps the section discoverable on the existing refresh
// and the actionable rows come from the dedicated owner endpoint.
async function loadMemoryCandidates(){
 const request=++memoryCandidateLoadSequence;
 try{const data=await api('/api/personal-space/memory-candidates');if(request!==memoryCandidateLoadSequence)return;memoryCandidateRows=data.candidates||[];memoryCandidateFingerprint='';renderMemoryCandidates();}catch(error){if(request===memoryCandidateLoadSequence)setError('memory-candidate-feedback',error);}
}
function renderMemoryCandidateSummary(space){
 const count=space?.memory_candidate_count||0;
 $('memory-candidate-summary').textContent=count?`검토 대기 ${count}개`:'검토 대기 없음';
 if(memoryCandidateReloadNeeded($('memory-candidates').open,count,memoryCandidateObservedCount)){memoryCandidateObservedCount=count;void loadMemoryCandidates();}
}
function renderMemoryCandidates(){
 const list=$('memory-candidate-list'),detail=$('memory-candidate-detail'),rows=memoryCandidateRows||[];
 if(selectedCandidateId&&!rows.some(row=>row.id===selectedCandidateId)){selectedCandidateId='';memoryCandidateReview=null;}
 const fingerprint=JSON.stringify([rows,selectedCandidateId,memoryCandidateReview]);if(memoryCandidateFingerprint===fingerprint)return;memoryCandidateFingerprint=fingerprint;
 list.replaceChildren();
 for(const row of rows){const button=element('button',undefined,'item-row'+(row.id===selectedCandidateId?' selected':''));button.type='button';button.append(element('strong',row.memory_key||'기억 키 없음'),element('span',`저장 전 후보 · ${safeTime(row.created)}`));button.onclick=()=>{selectedCandidateId=row.id;memoryCandidateReview=null;memoryCandidateFingerprint='';renderMemoryCandidates();};list.append(button);}
 if(!rows.length)list.append(element('p','검토를 기다리는 기억 후보가 없습니다.','muted'));
 const selected=rows.find(row=>row.id===selectedCandidateId);
 if(!selected)return detail.replaceChildren(element('p','후보를 선택하면 저장 전 내용을 확인할 수 있습니다.','empty-state'));
 detail.replaceChildren(element('p','저장 전 기억 후보','eyebrow'),element('h4',selected.memory_key||'기억 키 없음'),element('p',`제안 시각 ${safeTime(selected.created)}`,'muted'));
 const step=memoryCandidateStep(memoryCandidateReview,selected.id);
 if(step==='inspect'){
  detail.append(element('p','승인 전에는 기억으로 저장하지 않습니다. 검토를 눌러 이 후보의 현재 내용과 대조값을 확인하세요.','muted'));
  const inspect=element('button','검토');inspect.type='button';
  inspect.onclick=()=>busy(inspect,async()=>{try{const inspected=await api('/api/personal-space/memory-candidates/request',{operation:'inspect',id:selected.id,work_ref:selected.work_ref});memoryCandidateReview={inspected,approval:null};memoryCandidateFingerprint='';renderMemoryCandidates();$('memory-candidate-feedback').textContent='';}catch(error){setError('memory-candidate-feedback',error);}});
  return detail.append(inspect);
 }
 const inspected=memoryCandidateReview.inspected,actions=element('div',undefined,'button-row');
 detail.append(element('p',inspected.content||'내용이 제공되지 않았습니다.','outcome'),element('p',`검토한 내용 대조값 ${inspected.content_digest}`,'technical'));
 if(step==='request-approval'){
  const request=element('button','이 내용으로 승인 요청');request.type='button';
  request.onclick=()=>busy(request,async()=>{try{const approval=await api('/api/personal-space/memory-candidates/request',memoryCandidateDecisionBody(memoryCandidateReview,'request-approval'));memoryCandidateReview={inspected,approval};memoryCandidateFingerprint='';renderMemoryCandidates();$('memory-candidate-feedback').textContent='승인을 요청했습니다. 위 내용을 다시 확인한 뒤 승인을 확정하세요.';}catch(error){setError('memory-candidate-feedback',error);}});
  actions.append(request);
 }else{
  const accept=element('button','확인한 내용으로 승인 확정','primary');accept.type='button';
  accept.onclick=()=>busy(accept,async()=>{const body=memoryCandidateDecisionBody(memoryCandidateReview,'accept');if(!body)return setError('memory-candidate-feedback',new Error('검토한 내용과 승인이 일치하지 않습니다. 다시 검토하세요.'));try{await api('/api/personal-space/memory-candidates/request',body);memoryCandidateReview=null;selectedCandidateId='';$('memory-candidate-feedback').textContent='검토한 내용을 기억으로 저장했습니다.';await loadMemoryCandidates();await refreshLoadedRecords();await refresh();}catch(error){setError('memory-candidate-feedback',error);}});
  actions.append(accept);
  detail.append(element('p',`이 승인은 ${safeTime(memoryCandidateReview.approval.expires_at)}까지만 쓸 수 있고, 그 사이 기억이 바뀌면 무효가 됩니다.`,'technical'));
 }
 const reject=element('button','거부');reject.type='button';
 reject.onclick=()=>busy(reject,async()=>{const body=memoryCandidateDecisionBody(memoryCandidateReview,'reject');if(!body)return setError('memory-candidate-feedback',new Error('검토한 후보를 다시 확인하세요.'));try{await api('/api/personal-space/memory-candidates/request',body);memoryCandidateReview=null;selectedCandidateId='';$('memory-candidate-feedback').textContent='이 후보를 거부했습니다. 기억으로 저장하지 않습니다.';await loadMemoryCandidates();await refresh();}catch(error){setError('memory-candidate-feedback',error);}});
 actions.append(reject);detail.append(actions);
}
$('memory-candidates').ontoggle=()=>{if(!$('memory-candidates').open){memoryCandidateObservedCount=null;return;}memoryCandidateObservedCount=lastSpace?.memory_candidate_count??null;void loadMemoryCandidates();};

function rememberWorkspaceResultSummary(workspace,updated){workspaceResultSummaries.set(workspace.id,{updated,summary:workspaceResultSummary(workspace)});}
async function loadWorkspaceResultSummaries(workspaces){await Promise.all((workspaces||[]).map(async workspace=>{const cached=workspaceResultSummaries.get(workspace.id);if(cached&&cached.updated===workspace.updated)return;try{const detail=await api('/api/workspaces/'+encodeURIComponent(workspace.id));const current=lastHome?.workspaces?.find(item=>item.id===workspace.id);if(current&&current.updated===workspace.updated){rememberWorkspaceResultSummary(detail,workspace.updated);renderWorkspaces(lastHome,lastState);}}catch(_error){}}));}
async function selectWorkspace(id){selectedWorkspaceId=id;const request=++workspaceDetailSequence;document.querySelectorAll('.workspace-row').forEach(row=>row.classList.toggle('selected',row.dataset.workspaceId===id));try{const workspace=await api('/api/workspaces/'+encodeURIComponent(id));if(shouldRenderWorkspaceDetail(selectedWorkspaceId,id,request,workspaceDetailSequence)){rememberWorkspaceResultSummary(workspace,lastHome?.workspaces?.find(item=>item.id===id)?.updated);renderWorkspaceDetail(workspace);renderWorkspaces(lastHome,lastState);}}catch(error){if(shouldRenderWorkspaceDetail(selectedWorkspaceId,id,request,workspaceDetailSequence))setError('workspace-feedback',error);}}
function renderWorkspaceDetail(workspace){const detail=$('workspace-detail');detail.replaceChildren(element('h3',workspace.title),element('p',workspace.purpose||'설명 없음','muted'));const results=workspace.results||[];detail.append(element('h4','저장된 결과'));for(const result of results)detail.append(element('p',result.content||'내용 없음','workspace-result'));if(!results.length)detail.append(element('p','아직 저장된 결과가 없습니다.','muted'));const candidates=workspaceSaveCandidates(lastState?.jobs,workspace.id,workspace.saved_job_ids);for(const job of candidates){const button=element('button','완료 결과 저장');button.type='button';button.onclick=()=>busy(button,async()=>{const workspaceId=workspace.id,request=++workspaceDetailSequence;recordLoadSequence++;try{const saved=await api('/api/workspaces/'+encodeURIComponent(workspaceId)+'/save-result',{job_id:job.id}),current=lastHome?.workspaces?.find(item=>item.id===workspaceId);rememberWorkspaceResultSummary(saved,current?.updated);if(shouldRenderWorkspaceDetail(selectedWorkspaceId,workspaceId,request,workspaceDetailSequence))renderWorkspaceDetail(saved);$('workspace-feedback').textContent='완료 결과를 프로젝트에 저장했습니다.';await loadRecords();renderWorkspaces(lastHome,lastState);}catch(error){setError('workspace-feedback',error);}});detail.append(element('p',`${job.workspace_id?'이 프로젝트':'미지정 작업'} · ${job.response||job.message||'완료된 작업'}`),button);}}
function renderWorkspaces(home,state){const list=$('workspace-list'),workspaces=home?.workspaces||[],summaries=workspaces.map(workspace=>workspaceResultSummaries.get(workspace.id)?.summary?.label||'완료 결과 확인 중…'),fingerprint=JSON.stringify([workspaces,summaries]);if(list.dataset.state===fingerprint)return;list.dataset.state=fingerprint;list.replaceChildren();if(selectedWorkspaceId&&!workspaces.some(item=>item.id===selectedWorkspaceId))selectedWorkspaceId='';workspaces.forEach((workspace,index)=>{const row=element('button',undefined,'workspace-row'+(workspace.id===selectedWorkspaceId?' selected':''));row.type='button';row.dataset.workspaceId=workspace.id;row.append(element('strong',workspace.title),element('span',summaries[index]));row.onclick=()=>selectWorkspace(workspace.id);list.append(row);});if(!workspaces.length)list.append(element('p','프로젝트가 없습니다.','muted'));}
