function renderContext(inbox){if(!inbox)return;if(!contextDraftDirty&&!['context-text','context-url'].includes(document.activeElement?.id)){$('context-text').checked=!!inbox.sources?.text;$('context-url').checked=!!inbox.sources?.url;}let warning=$('context-sharing-warning');if(!warning){warning=element('p');warning.id='context-sharing-warning';$('context-telegram-policy').after(warning);}warning.textContent=inbox.sharing_requires_policy_and_per_request_approval?'이 정책을 허용해도 각 Telegram 작업마다 공유 승인이 필요합니다.':'';const list=$('context-items');list.replaceChildren();for(const item of inbox.items||[]){const row=element('div',undefined,'record-row');row.append(element('span',`${item.source_kind} · ${safeTime(item.captured_at)} · ${safeTime(item.expires_at)} 만료`));const remove=element('button','삭제');remove.type='button';remove.onclick=()=>busy(remove,async()=>{try{await api('/api/context-inbox/delete',{id:item.id});await refresh();}catch(error){setError('context-feedback',error);}});row.append(remove);list.append(row);}if(!(inbox.items||[]).length)list.append(element('p','저장된 임시 자료가 없습니다.','muted'));}
