function renderCapabilityPreview(row,preview){let review=row.querySelector('.capability-preview');if(review)review.remove();review=element('div',undefined,'capability-preview');review.append(element('p',preview.effect||`${preview.target} ${preview.action}`));const actions=element('div',undefined,'button-row'),confirm=element('button','확인'),cancel=element('button','취소');confirm.type=cancel.type='button';confirm.onclick=()=>busy(confirm,async()=>{try{await api('/api/settings/request',{operation:'confirm',draft_id:preview.id,digest:preview.digest});$('capability-feedback').textContent='기능 권한 상태를 변경했습니다.';await refresh();}catch(error){setError('capability-feedback',error);}});cancel.onclick=()=>busy(cancel,async()=>{try{await api('/api/settings/request',{operation:'cancel',draft_id:preview.id,digest:preview.digest});review.remove();$('capability-feedback').textContent='변경을 취소했습니다.';}catch(error){setError('capability-feedback',error);}});actions.append(confirm,cancel);review.append(actions);row.append(review);}
// Owner-visible words for the four contract states.  An unknown value is
// reported as unknown rather than guessed as connected: a wrong 'connected'
// here would tell the owner an authorization exists that does not.
const CONNECTOR_STATES={disconnected:'연결 안 됨',connected:'연결됨',reauth_required:'다시 인증 필요',blocked:'차단됨'};
const CONNECTOR_NAMES={'google-gmail-read':'Google Gmail','google-calendar':'Google Calendar','google-calendar-write':'Google Calendar','google-drive-read':'Google Drive'};
const CAPABILITY_NAMES={'google-drive-read':'Google Drive 파일 읽기','compatibility-a2a-peer':'외부 에이전트 연결','google-calendar-create':'Google Calendar 일정 만들기','builtin-mcp-read':'내 컴퓨터 파일 읽기'};
const CAPABILITY_STATES={available:'사용 가능','connected-disabled':'연결됨 · 사용 안 함',enabled:'사용 설정됨',paused:'일시 정지','auth-required':'다시 인증 필요',error:'오류',disconnected:'연결 안 됨'};
const CAPABILITY_STATE_KINDS={available:'neutral','connected-disabled':'neutral',enabled:'active',paused:'neutral','auth-required':'attention',error:'attention',disconnected:'neutral'};
const CAPABILITY_DESTINATIONS={'google-drive-read':'Google','google-calendar-create':'Google','compatibility-a2a-peer':'외부 에이전트'};
function directRouteName(model){const provider=displayProvider(model),name=providerNames[provider]||provider;return provider==='openai'?'OpenAI Developer API':name;}
function capabilityBoundary(capability){const destination=CAPABILITY_DESTINATIONS[capability?.id];if(destination)return `외부 연결 권한 · ${destination}`;if(capability?.id==='builtin-mcp-read')return '로컬 기능 권한';if(capability?.kind==='runtime')return '런타임 권한';return '기능 권한';}
// The connect action is a plain same-origin navigation, not an api() call:
// /google-gmail answers 303 to Google, which fetch would follow cross-origin
// and discard.  The href stays relative so the owner-session cookie, which is
// SameSite=Strict and host-scoped, travels whether AgentOS was opened at
// 127.0.0.1 or localhost.  Drawing the link grants nothing; the route still
// requires that session and still refuses a tunnel host.
function renderConnectors(connectors){const box=$('connector-controls');if(!box)return;const rows=connectors||[],fingerprint=JSON.stringify(rows);if(box.dataset.state===fingerprint)return;box.dataset.state=fingerprint;box.replaceChildren();for(const connector of rows){const id=String(connector.connector_id||''),backendLabel=String(connector.label||'').trim(),name=CONNECTOR_NAMES[id]||(backendLabel&&backendLabel!==id?backendLabel:'기타 연결'),state=CONNECTOR_STATES[connector.state]||'확인 필요',kind=connector.state==='connected'?'active':connector.state==='reauth_required'||connector.state==='blocked'?'attention':'neutral',lines=[`연결 ID: ${id||'정보 없음'}`,`요청 권한: ${(connector.required_scopes||[]).join(', ')||'요청 권한 없음'}`],disclosure=settingsDisclosure('세부 정보',lines);let action=null;if(connector.connect_path&&connector.state!=='blocked'){const link=element('a',connector.state==='connected'?'다시 연결':connector.state==='reauth_required'?'다시 연결':'연결','button-link settings-row-action');link.href=connector.connect_path;link.rel='noreferrer';action=link;}const description=connector.detail||connector.description||(connector.state==='blocked'?'현재 정책으로 사용할 수 없습니다.':'연결 상태와 권한을 확인합니다.');box.append(settingsRow(name,description,state,kind,action,disclosure));}if(!rows.length)box.append(element('p','이 설치에 구성된 외부 연결이 없습니다.','muted'));}
function renderCapabilities(model){const box=$('capability-controls'),fingerprint=JSON.stringify(model||{});if(box.dataset.state===fingerprint)return;box.dataset.state=fingerprint;box.replaceChildren();for(const capability of model?.capabilities||[]){const id=String(capability.id||''),name=CAPABILITY_NAMES[id]||'기타 기능',state=CAPABILITY_STATES[capability.state]||'상태 정보 없음',kind=CAPABILITY_STATE_KINDS[capability.state]||'attention',actions=capabilityActions(capability),labels={pause:'일시 정지',disconnect:'연결 해제',resume:'다시 시작'},disclosure=settingsDisclosure('세부 정보',[`기능 ID: ${id||'정보 없음'}`,`상태: ${String(capability.state||'알 수 없음')}`,capability.recovery||'복구 안내 없음']),primaryAction=actions.includes('pause')?settingsAction(labels.pause,async event=>requestCapabilityDraft(event.currentTarget,capability,'pause')):actions.includes('resume')?settingsAction(labels.resume,async event=>requestCapabilityDraft(event.currentTarget,capability,'resume')):null,row=settingsRow(name,capabilityBoundary(capability),state,kind,primaryAction,disclosure);if(actions.includes('disconnect')){const disconnect=settingsAction(labels.disconnect,async event=>requestCapabilityDraft(event.currentTarget,capability,'disconnect'),'destructive');const more=element('details',undefined,'settings-more-actions'),summary=element('summary','추가 작업');more.append(summary,disconnect);row.querySelector('.settings-row-main').append(more);}box.append(row);}if(!(model?.capabilities||[]).length)box.append(element('p','검토된 로컬 기능이 없습니다.','muted'));}
async function requestCapabilityDraft(button,capability,action){await busy(button,async()=>{try{const response=await api('/api/settings/request',{operation:'draft',intent:`${capability.id} ${action}`});renderCapabilityPreview(button.closest('.settings-row'),response.preview);}catch(error){setError('capability-feedback',error);}});}
