$('connect-openrouter').onclick=async()=>{const popup=window.open('about:blank','agentos-openrouter');try{const bytes=crypto.getRandomValues(new Uint8Array(48)),verifier=btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)),challenge=btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const state=crypto.randomUUID(),callback=location.origin+'/?state='+encodeURIComponent(state),url='https://openrouter.ai/auth?'+new URLSearchParams({callback_url:callback,code_challenge:challenge,code_challenge_method:'S256'});localStorage.setItem('openrouter-flow',JSON.stringify({verifier,state,url,expires:Date.now()+600000}));$('resume-openrouter').hidden=false;if(popup)popup.location.href=url;}catch(error){setError('easy-feedback',error);}};
function restoreOpenRouterFlow(){const flow=parseOpenRouterFlow(localStorage.getItem('openrouter-flow'));if(!flow)localStorage.removeItem('openrouter-flow');$('resume-openrouter').hidden=!flow;return flow;}
async function finishOpenRouter(){const params=new URLSearchParams(location.search);if(!params.has('code'))return;const flow=restoreOpenRouterFlow();history.replaceState(null,'',location.pathname+'#settings/ai');navigate('settings','ai');try{if(!flow||flow.state!==params.get('state'))throw new Error('연결 시간이 지났습니다. 다시 시작하세요.');await api('/api/openrouter/connect',{code:params.get('code'),verifier:flow.verifier});localStorage.removeItem('openrouter-flow');$('resume-openrouter').hidden=true;if(window.opener&&!window.opener.closed){window.opener.postMessage({type:'agentos-openrouter-connected'},location.origin);window.close();return;}invalidateModelLoad();$('api-key').value='';invalidateModelDraft('연결 결과가 바뀌었습니다. 적용 전에 다시 테스트하세요.');$('easy-feedback').textContent='OpenRouter 연결 결과를 저장했습니다.';await refresh();}catch(error){setError('easy-feedback',error);}}
window.addEventListener('message',event=>{if(!isOpenRouterCompletion(event,location.origin))return;localStorage.removeItem('openrouter-flow');$('resume-openrouter').hidden=true;invalidateModelLoad();$('api-key').value='';invalidateModelDraft('연결 결과가 바뀌었습니다. 적용 전에 다시 테스트하세요.');$('easy-feedback').textContent='OpenRouter 연결 결과를 저장했습니다.';void refresh();});
